use std::{net::SocketAddr, sync::Arc};

use bootstrap::{config::AppConfig, router::build_router};
use sqlx::sqlite::SqlitePoolOptions;
use state::AppState;
use tokio::sync::broadcast;
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

use std::path::PathBuf;
use crate::modules::plugin::loader::PluginLoader;
use crate::modules::plugin::manager::PluginManager;

pub async fn serve() -> anyhow::Result<()> {
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "inkforge=info,axum=info,tower_http=info".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    let config = AppConfig::load()?;
    config.validate()?;

    // 妫€娴?Turnstile 閰嶇疆涓嶄竴鑷达細secret 宸查厤缃絾 site_key 涓虹┖
    if !config.auth.turnstile_secret.is_empty() && config.auth.turnstile_site_key.is_empty() {
        tracing::warn!(
            "Turnstile verification is configured (turnstile_secret is set) but turnstile_site_key is empty. \
             The Turnstile widget will not render on the login page, but backend validation is enabled. \
             This is likely a configuration error 鈥?set INKFORGE__AUTH__TURNSTILE_SITE_KEY to match."
        );
    }
    std::fs::create_dir_all(&config.storage.upload_dir)?;
    std::fs::create_dir_all(&config.theme.theme_dir)?;

    let pool = SqlitePoolOptions::new()
        .max_connections(5)
        .connect(&config.database.url)
        .await?;
    sqlx::query("PRAGMA foreign_keys = ON")
        .execute(&pool)
        .await?;
    sqlx::query("PRAGMA journal_mode=WAL")
        .execute(&pool)
        .await?;
    sqlx::query("PRAGMA synchronous=NORMAL")
        .execute(&pool)
        .await?;
    sqlx::migrate!("./migrations").run(&pool).await?;

    // 鍒涘缓 WebSocket broadcast channel锛屽閲?256
    let (event_tx, _rx) = broadcast::channel::<ws::ServerEvent>(256);

    let setup_runtime = modules::setup::service::bootstrap_runtime(&pool).await?;

    // TODO: 绛夊緟 plugin_registry.rs 鐢熸垚
    // register_all().await;

    let loader = PluginLoader::new(
        PathBuf::from("plugins"),
        env!("CARGO_PKG_VERSION"),
    );
    let discovered = loader.discover(&pool).await?;
    let plugin_manager = Arc::new(tokio::sync::RwLock::new(PluginManager::load_with(discovered).await));

    let state = Arc::new(AppState::new(
        config.clone(),
        pool,
        event_tx,
        setup_runtime.site_url,
        setup_runtime.admin_url,
        setup_runtime.stage,
        plugin_manager.clone(),
    )?);

    state.plugin_manager.write().await.init_all(&state).await?;
    // 鍒濆鍖?Webhook 鍒嗗彂鍣紝娉ㄥ唽鍒板叏灞€ HookRegistry
    {
        let dispatcher = modules::webhook::service::WebhookDispatcher::new(state.pool.clone(), config.webhook.clone());
        let hooks = dispatcher.into_hooks();
        state.plugin_manager.read().await.hook_registry().register("webhook", hooks).await;
    }
    modules::backup::scheduler::start_backup_scheduler(state.clone()).await?;
    modules::trash::scheduler::start_trash_scheduler(state.clone()).await?;

    // 鍚姩涓婚鏂囦欢鐩戝惉鍣紙浠呭紑鍙戞ā寮忥級銆?
    // 澶辫触涓嶉樆姝㈡湇鍔″惎鍔?鈥斺€?閫€鍖栦负"淇敼鍚庢墜鍔ㄩ噸鍚?妯″紡鍗冲彲銆?
    if let Err(e) = infra::file_watcher::spawn_theme_watcher(state.clone(), &state.theme_dir) {
        tracing::warn!(error = ?e, "failed to start theme file watcher; continuing without hot-reload");
    }

    let app = build_router(state).await;

    let addr = SocketAddr::new(config.server.host.parse()?, config.server.port);
    tracing::info!("InkForge listening on http://{}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;
    Ok(())
}
