/// 鍙戦€佸崟涓?webhook 璇锋眰锛屾敮鎸侀噸璇?
async fn send_webhook_with_retry(
    client: &Client,
    webhook: &Webhook,
    payload: &str,
) -> (bool, Option<i64>, String) {
    let max_retries = webhook.max_retries.min(5); // 鏈€澶?5 娆￠噸璇?
    let mut last_status: Option<i64> = None;
    let mut last_body = String::new();

    for attempt in 0..=max_retries {
        if attempt > 0 {
            // 鏍囧噯鎸囨暟閫€閬? 5 * 2^(attempt-1), 涓婇檺 60 绉?
            let delay_secs = (INITIAL_DELAY_SECONDS_FOR_WEBHOOK_RETRY
                * 2u64.pow(attempt as u32 - 1))
            .min(60);
            tracing::warn!(
                module = "webhook",
                webhook_id = %webhook.id,
                attempt = attempt,
                delay_secs = delay_secs,
                "retrying webhook delivery"
            );
            sleep(Duration::from_secs(delay_secs)).await;
        }

        match try_send_webhook(client, webhook, payload).await {
            Ok((status, body)) => {
                if status >= 200 && status < 300 {
                    return (true, Some(status), body);
                }
                // 4xx 瀹㈡埛绔敊璇笉閲嶈瘯
                if status >= 400 && status < 500 {
                    tracing::warn!(
                        module = "webhook",
                        webhook_id = %webhook.id,
                        status = status,
                        "webhook client error, not retrying"
                    );
                    return (false, Some(status), body);
                }
                last_status = Some(status);
                last_body = body;
            }
            Err(e) => {
                last_body = e.to_string();
                tracing::error!(
                    module = "webhook",
                    webhook_id = %webhook.id,
                    attempt = attempt,
                    error = %e,
                    "webhook request failed"
                );
            }
        }
    }

    (false, last_status, last_body)
}

/// 妫€鏌?IP 鍦板潃鏄惁涓虹鏈夋垨鏈湴鍦板潃
fn is_private_ip(ip: &std::net::IpAddr) -> bool {
    match ip {
        std::net::IpAddr::V4(ipv4) => {
            // 0.0.0.0/8
            ipv4.octets()[0] == 0
                // 10.0.0.0/8
                || ipv4.octets()[0] == 10
                // 127.0.0.0/8 (loopback)
                || ipv4.octets()[0] == 127
                // 169.254.0.0/16 (link-local)
                || (ipv4.octets()[0] == 169 && ipv4.octets()[1] == 254)
                // 172.16.0.0/12
                || (ipv4.octets()[0] == 172 && (ipv4.octets()[1] >= 16 && ipv4.octets()[1] <= 31))
                // 192.168.0.0/16
                || (ipv4.octets()[0] == 192 && ipv4.octets()[1] == 168)
        }
        std::net::IpAddr::V6(ipv6) => {
            // ::1 (loopback)
            *ipv6 == Ipv6Addr::LOCALHOST
                // :: (unspecified)
                || ipv6.is_unspecified()
                // fe80::/10 (link-local)
                || (ipv6.segments()[0] & 0xffc0 == 0xfe80)
                // fc00::/7 (unique local)
                || (ipv6.segments()[0] & 0xfe00 == 0xfc00)
        }
    }
}

/// 鏋勫缓绛惧悕澶?
fn build_hmac_signature(secret: &str, body: &str) -> String {
    let mut mac = Hmac::<Sha256>::new_from_slice(secret.as_bytes())
        .expect("HMAC can take key of any size");
    mac.update(body.as_bytes());
    let result = mac.finalize();
    format!("sha256={}", hex::encode(result.into_bytes()))
}

